// Los 17 productos pack segun la planilla de Mariano (16-jul-2026).
// name = titulo que ve el cliente (bobinas/unidades, no kg)
// precio = precio a publicar / 1.21 (neto para Odoo; WF1 le re-agrega el IVA)
// attrs = atributos requeridos de ML precargados
const A = (m) => JSON.stringify([
  {id:'BRAND',value_name:'Embalog'},{id:'MODEL',value_name:m},
  {id:'VALUE_ADDED_TAX',value_name:'21%'},{id:'IMPORT_DUTY',value_name:'0%'}
]);
const PACKS = [
  ['Cinta Embalaje Transparente 24mm x 45m Pack 72 Unidades',45500,'24mm x 45m x72'],
  ['Cinta De Papel Rapifix 48 Mm X 50 Mts Pack 18 Unidades',169500,'48mm x 50m x18'],
  ['Film Alimenticio 45 Cm X 600 Mts Pack 4 Rollos',128000,'45cm x 600m x4'],
  ['Film Stretch Automatico 50 Cm 7.5 Kg Pack 3 Bobinas',134500,'7.5 Kg x 3'],
  ['Film Stretch Negro 10 Cm 0.5 Kg Pack 25 Unidades',92000,'0.5 Kg x 25'],
  ['Film Stretch Negro Con Mango 2.8 Kg Pack 4 Bobinas',76000,'2.8 Kg x 4'],
  ['Film Stretch Negro Con Mango 4 Kg Pack 4 Bobinas',111500,'4 Kg x 4'],
  ['Film Stretch Negro Sin Mango 3.5 Kg Pack 4 Bobinas',65000,'3.5 Kg x 4'],
  ['Film Stretch Negro Sin Mango 4.5 Kg Pack 4 Bobinas',92500,'4.5 Kg x 4'],
  ['Film Stretch Negro Sin Mango 5 Kg Pack 4 Bobinas',114000,'5 Kg x 4'],
  ['Film Stretch Transparente 10 Cm 0.5 Kg Pack 25 Unidades',87000,'0.5 Kg x 25'],
  ['Film Stretch Transparente Con Mango 2.8 Kg Pack 4 Bobinas',71000,'2.8 Kg x 4'],
  ['Film Stretch Transparente Con Mango 4 Kg Pack 4 Bobinas',104000,'4 Kg x 4'],
  ['Film Stretch Transparente Sin Mango 4 Kg Pack 4 Bobinas',79000,'4 Kg x 4'],
  ['Film Stretch Transparente Sin Mango 4.5 Kg Pack 4 Bobinas',92500,'4.5 Kg x 4'],
  ['Film Stretch Transparente Sin Mango 5 Kg Pack 4 Bobinas',106500,'5 Kg x 4'],
  ['Film Stretch Transparente Sin Mango 3.5 Kg Pack 4 Bobinas',65000,'3.5 Kg x 4']
];
return PACKS.map(([n,p,m]) => ({ json: {
  name: n,
  precio: Math.round(p/1.21*100)/100,
  attrs: A(m)
}}));

// Pesos de los packs (en gramos) para cotizar Mercado Envios.
// Caja generica 30x40x50 cm. 7000g = la caja x36 de cinta ya publicada.
const pesos = [5000,7000,9000,12000,13000,14500,16500,18000,18500,20500,23000];
return pesos.map(p => ({ json: { peso: p } }));
